using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "recent advances in quantum computing 2026";

Console.WriteLine($"Research Agent — topic: \"{topic}\"");
Console.WriteLine(new string('─', 60));

// Build the chat client via MEAI abstraction
IChatClient chatClient = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey)
            .GetChatClient("gpt-4o-2024-08-06")
            .AsIChatClient())
    .Build();

// Set up the tools the agent can use
var researchTools = new ResearchTools();
var tools = new AITool[]
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.TakeNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

// Create the agent with the Agent Framework
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your goal is to thoroughly research a topic by:
        1. Searching the web for relevant information (make multiple searches with different queries)
        2. Taking notes on key findings as you go
        3. Once you have gathered enough information, retrieve all your notes and produce a final summary

        Always take notes on important findings before moving to the next search.
        When you have enough information (at least 3 searches), retrieve your notes and write a comprehensive summary.
        """,
    Tools = tools,
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Temperature = 0f,
};

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

// Run the agent loop
Console.WriteLine("\n🔍 Researching...\n");

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n" + new string('─', 60));
Console.WriteLine("✅ Research complete.");

// --- Tool implementations ---

public sealed class ResearchTools
{
    private static readonly HttpClient Http = new();
    private readonly List<string> _notes = [];

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var request = new HttpRequestMessage(HttpMethod.Get,
                $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1");
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var response = await Http.SendAsync(request);
            response.EnsureSuccessStatusCode();

            var json = await response.Content.ReadFromJsonAsync<JsonElement>();

            var results = new List<string>();

            // Abstract text
            if (json.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
            {
                results.Add($"[Summary] {abstractText}");
            }

            // Related topics
            if (json.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } snippet)
                    {
                        results.Add(snippet);
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : "No results found. Try a different search query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Take a note to remember an important finding during research.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note taken ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all notes taken so far during research.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        Console.WriteLine($"  📋 Retrieving {_notes.Count} notes");
        return string.Join("\n---\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }
}

